def can_use_flashinfer_moe(use_fp8_w8a8: bool, use_int4_w4a16: bool,
                            block_shape: Optional[List[int]]) -> bool:
    """Check if FlashInfer MoE kernels can be used."""
    # FlashInfer MoE kernels support FP8 and FP4 quantization
    if use_fp8_w8a8 and envs.VLLM_USE_FLASHINFER_MOE_FP8:
        # For FP8, we support both per-tensor and block-wise quantization
        return True
    if use_int4_w4a16 and envs.VLLM_USE_FLASHINFER_MOE_FP4:
        # For FP4, we currently only support per-tensor quantization
        return block_shape is None
    return False


